// ============================================================
// config.js — Reads all configuration from config.xlsx.
// DO NOT edit this file each release; edit config.xlsx instead.
// Run create_config_xlsx.js once to generate config.xlsx.
//
// Override logic (applies to every tab):
//   "Overridden Value" column non-empty → use it
//   "Overridden Value" column blank     → fall back to "Default Value"
// ============================================================

const path = require('path');
const fs   = require('fs');

const CONFIG_XLSX = path.join(__dirname, '..', 'config.xlsx');

if (!fs.existsSync(CONFIG_XLSX)) {
  console.error('ERROR: config.xlsx not found at', CONFIG_XLSX);
  console.error('Run:  node scripts/create_config_xlsx.js  to generate it.');
  process.exit(1);
}

const XLSX = (() => {
  const candidates = [
    '' + require('os').homedir().replace(/\\/g, '/') + '/node_modules/xlsx',
    path.join(__dirname, '..', '..', '..', '..', 'node_modules', 'xlsx'),
  ];
  for (const c of candidates) {
    if (fs.existsSync(c)) return require(c);
  }
  return require('xlsx');
})();

function resolve(defaultVal, overriddenVal) {
  const ov = (overriddenVal !== undefined && overriddenVal !== null)
    ? String(overriddenVal).trim()
    : '';
  return ov !== '' ? ov : String(defaultVal !== undefined && defaultVal !== null ? defaultVal : '').trim();
}

// Key | Default Value | Overridden Value | Description/Notes
function parseKeyValueSheet(ws) {
  const rows = XLSX.utils.sheet_to_json(ws, { header: 1 });
  const map = {};
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || !row[0]) continue;
    map[String(row[0]).trim()] = resolve(row[1], row[2]);
  }
  return map;
}

// jar_location sheet: Module | From | To | Shared Folder | Notes
function parseJarLocation(ws) {
  const rows = XLSX.utils.sheet_to_json(ws, { header: 1 });
  const map = {};
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || !row[0]) continue;
    const mod = String(row[0]).trim();
    if (!mod) continue;
    map[mod] = {
      from:         row[1] ? String(row[1]).trim() : '',
      to:           row[2] ? String(row[2]).trim() : '',
      sharedFolder: row[3] ? String(row[3]).trim() : '',
    };
  }
  return map;
}

const wb = XLSX.readFile(CONFIG_XLSX);

const general    = parseKeyValueSheet(wb.Sheets['General']);
const docker     = parseKeyValueSheet(wb.Sheets['Docker_VM']);
const jarLocMap  = wb.Sheets['jar_location'] ? parseJarLocation(wb.Sheets['jar_location']) : {};

const nodeModules = general['nodeModules'] || '' + require('os').homedir().replace(/\\/g, '/') + '/node_modules';

module.exports = {
  paths: {
    nodeModules,
    // setBranchFile is a legacy fallback; the real source is SRCDIR env var / ~/.default-branch
    setBranchFile: general['setBranchFile'] || '',
    payorRepoRoot: general['payorRepoRoot'] || '' + require('os').homedir().replace(/\\/g, '/') + '/hebb',
    sharedFolder:  general['sharedFolder']  || '' + require('os').homedir().replace(/\\/g, '/') + '/shared',
  },

  docker: {
    containerName:         docker['containerName']         || 'payer-tc-261',
    weblogicContainerName: docker['weblogicContainerName'] || 'payer-wl-261',
    user:                  docker['dockerUser']            || 'weblogic',
    password:              docker['dockerPassword']        || '',
    deployDir:             docker['deployDir']             || '/home/weblogic/domains/healthedge/jars',
  },

  // jarLocMap[moduleName] = { from, to, sharedFolder }
  // Empty string means "use auto-detection"
  jarLocMap,
};
